import sys

def main():
    lines = sys.stdin.read().split()
    if not lines: return
    n, target = int(lines[0]), int(lines[1])
    nums = [int(x) for x in lines[2:2+n]]
    seen = {}
    for i, x in enumerate(nums):
        diff = target - x
        if diff in seen:
            print(f"{seen[diff]} {i}")
            return
        seen[x] = i

